import React from 'react'
import axios from 'axios'
import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import Success from '../../success'
import Form from 'react-bootstrap/Form';
import Button from 'react-bootstrap/esm/Button'

const Login = () => {
  const [userName, setUserName] = useState("");
  const [password, setPassword] = useState("");
  const [user, setUser] = useState(null);
  const navigate = useNavigate();

  const handleLogin = async () => {
    if (!userName || !password) {
      alert("Please enter both username and password");
      return;
    }
    try {
        let userData = await axios.get(`http://localhost:5000/students/${userName}`);
    if (userData.data.password === password) {
    //   navigate("/dashboard");
    setUser(userData.data);
} else {
    alert("Invalid username or password");
}
} catch (error) {
    alert("An error occurred while logging in");
}

};

if (user) {
  return <Success name={user.fullName} type="logged in" />;
}

  return (
    <div className=''>
      <h3>Enter your username and password</h3>
      <Form>
      <Form.Group className="mb-3" controlId="formGroupEmail">
        <Form.Label>Username</Form.Label>
        <Form.Control type="text" placeholder="Enter username" value={userName} onChange={(e) => setUserName(e.target.value)} />
      </Form.Group>
      <Form.Group className="mb-3" controlId="formGroupPassword">
        <Form.Label>Password</Form.Label>
        <Form.Control type="password" placeholder="Password" value={password} onChange={(e) => setPassword(e.target.value)} />
      </Form.Group>
      <div className='d-flex'>
        <p className='mt-3'>Don't have an account? </p>
      <Button variant="link" onClick={() => navigate("/signup")}>Signup</Button>
      </div>
      <div className='d-flex justify-content-between'>
      <Button variant="dark-outline" onClick={() => navigate("/")}>Back to Home</Button>
      <Button variant="primary" onClick={handleLogin}>Login</Button>
      </div>
      </Form>
    </div>
  )
}

export default Login
